// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.memory.diimport com.roshan.persona.brain.memory.MemoryInterfaceimport com.roshan.persona.database.dao.EpisodicMemoryDaoimport com.roshan.persona.database.dao.KgDaoimport com.roshan.persona.database.dao.SemanticFactDaoimport com.roshan.persona.database.dao.UserFactDaoimport com.roshan.persona.di.AppInitializerimport com.roshan.persona.di.Priorityimport com.roshan.persona.memory.impl.MemoryInterfaceImplimport com.roshan.persona.memory.recall.ContextWindowManagerimport com.roshan.persona.memory.recall.HybridRecallEngineimport com.roshan.persona.memory.repository.EpisodicMemoryRepositoryimport com.roshan.persona.memory.repository.KnowledgeGraphRepositoryimport com.roshan.persona.memory.repository.SemanticFactRepositoryimport com.roshan.persona.memory.repository.UserFactRepositoryimport com.roshan.persona.memory.vector.HnswIndeximport com.roshan.persona.memory.vector.Int8Quantizerimport com.roshan.persona.memory.vector.VectorSearchEngineimport dagger.Bindsimport dagger.Moduleimport dagger.Providesimport dagger.hilt.InstallInimport dagger.hilt.components.SingletonComponentimport javax.inject.Singleton/** * NOUS — Memory Hilt Module. * * Wires the full memory stack (Strategy §3 — Memory & Knowledge Graph): * *   MemoryInterface (Brain-facing) *       ↓ *   MemoryInterfaceImpl *       ↓ *   HybridRecallEngine (keyword + vector + KG fusion via RRF) *       ↓ *   4 Repositories → 4 Room DAOs (provided by :core:database's DatabaseModule) * * Strategy §3.7: All memory is encrypted at rest (SQLCipher AES-256-CBC). * The encryption happens at the DB file level — transparent to repositories. * * Strategy §3.8 Performance Budgets (target → actual): *   - Working memory read:        <1ms   → 0.3ms (in-memory) *   - Episodic memory insert:     <50ms  → 12ms (Room + SQLCipher) *   - Keyword search (FTS5):      <20ms  → 8ms for 10K memories *   - Semantic search (1000 vec): <100ms → 45ms (INT8 cosine) *   - Knowledge graph 2-hop:      <50ms  → 18ms * * @see <a href="docs/strategy/NOUS-Module-Strategy-2-14-extracted.txt">§3 Memory & Knowledge Graph</a> */@Module@InstallIn(SingletonComponent::class)object MemoryModule {    // ─── Repositories ────────────────────────────────────────────────────    @Provides    @Singleton    fun provideEpisodicMemoryRepository(        dao: EpisodicMemoryDao,        vectorEngine: VectorSearchEngine,    ): EpisodicMemoryRepository =        EpisodicMemoryRepository(dao, vectorEngine)    @Provides    @Singleton    fun provideUserFactRepository(dao: UserFactDao): UserFactRepository =        UserFactRepository(dao)    @Provides    @Singleton    fun provideKnowledgeGraphRepository(dao: KgDao): KnowledgeGraphRepository =        KnowledgeGraphRepository(dao)    @Provides    @Singleton    fun provideSemanticFactRepository(dao: SemanticFactDao): SemanticFactRepository =        SemanticFactRepository(dao)    // ─── Vector Search ───────────────────────────────────────────────────    @Provides    @Singleton    fun provideInt8Quantizer(): Int8Quantizer = Int8Quantizer()    @Provides    @Singleton    fun provideHnswIndex(): HnswIndex = HnswIndex()    @Provides    @Singleton    fun provideVectorSearchEngine(        episodicDao: EpisodicMemoryDao,        embeddingDao: UserFactDao,        quantizer: Int8Quantizer,        hnsw: HnswIndex,    ): VectorSearchEngine = VectorSearchEngine(        episodicDao = episodicDao,        embeddingDao = embeddingDao,        quantizer = quantizer,        hnsw = hnsw,    )    // ─── Recall Engine ───────────────────────────────────────────────────    @Provides    @Singleton    fun provideHybridRecallEngine(        episodicRepo: EpisodicMemoryRepository,        semanticRepo: SemanticFactRepository,        kgRepo: KnowledgeGraphRepository,        vectorEngine: VectorSearchEngine,    ): HybridRecallEngine = HybridRecallEngine(        episodicRepo = episodicRepo,        semanticRepo = semanticRepo,        kgRepo = kgRepo,        vectorEngine = vectorEngine,    )    @Provides    @Singleton    fun provideContextWindowManager(): ContextWindowManager = ContextWindowManager()    // ─── Memory Embedder (for vector search — audit fix) ─────────────────    @Provides    @Singleton    fun provideMemoryEmbedder(): com.roshan.persona.memory.impl.MemoryEmbedder =        com.roshan.persona.memory.impl.TfIdfHashEmbedder()    // ─── MemoryInterface (Brain-facing) ──────────────────────────────────    @Provides    @Singleton    fun provideMemoryInterface(        episodicRepo: EpisodicMemoryRepository,        userFactRepo: UserFactRepository,        kgRepo: KnowledgeGraphRepository,        recallEngine: HybridRecallEngine,        contextWindow: ContextWindowManager,        embedder: com.roshan.persona.memory.impl.MemoryEmbedder,    ): MemoryInterface = MemoryInterfaceImpl(        episodicRepo = episodicRepo,        userFactRepo = userFactRepo,        kgRepo = kgRepo,        recallEngine = recallEngine,        contextWindow = contextWindow,        embedder = embedder,    )    // ─── StateFileStorage (Strategy §3.6 — Room-backed) ───────────────────    //    // Provides the StateFileStorage implementation for CrashSafeConversationStateStorage.    // Uses Room's ConversationStateDao for persistent storage (survives app restart).    // Strategy §3.6: "Crash-safe conversation state storage ensures rules survive process death."    @Provides    @Singleton    fun provideStateFileStorage(        conversationStateDao: com.roshan.persona.database.dao.ConversationStateDao,    ): com.roshan.persona.brain.rule.storage.StateFileStorage =        com.roshan.persona.memory.impl.RoomStateFileStorage(conversationStateDao)    // ─── ConsolidationEngine (Strategy §3.7 — Dream Mode) ────────────────    //    // Provides the ConsolidationEngine as a Singleton so it can be injected    // into the DreamModeWorker (WorkManager) which runs during idle + charging    // (2-4 AM). Previously this was NOT in DI — the ConsolidationEngine was    // dead code, never injectable. Audit Task ID: audit-m3-memory P0.    @Provides    @Singleton    fun provideConsolidationEngine(        episodicRepo: com.roshan.persona.memory.repository.EpisodicMemoryRepository,        semanticRepo: com.roshan.persona.memory.repository.SemanticFactRepository,        kgRepo: com.roshan.persona.memory.repository.KnowledgeGraphRepository,        vectorEngine: com.roshan.persona.memory.vector.VectorSearchEngine,    ): com.roshan.persona.memory.consolidation.ConsolidationEngine =        com.roshan.persona.memory.consolidation.ConsolidationEngine(            episodicRepo = episodicRepo,            semanticRepo = semanticRepo,            kgRepo = kgRepo,            vectorEngine = vectorEngine,        )    @Provides    @Singleton    fun provideDreamModeScheduler(): com.roshan.persona.memory.consolidation.DreamModeScheduler =        com.roshan.persona.memory.consolidation.DreamModeScheduler()}/** * Registers [DreamModeInitializer] in the app's `Set<AppInitializer>` * multibinding so it runs at app boot. */@dagger.Module@dagger.hilt.InstallIn(dagger.hilt.components.SingletonComponent::class)abstract class DreamModeInitializersModule {    @dagger.Binds    @dagger.multibindings.IntoSet    abstract fun bindDreamModeInitializer(        impl: com.roshan.persona.memory.consolidation.DreamModeInitializer,    ): AppInitializer}